def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    labels = [i for i in range(n)]
    shifts = [[0, 0, 0] for i in range(n)]
    periodic = [False for i in range(n)]
    bonded = [False for i in range(n)]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0):
            continue
        if occ[i] <= 0.0 or occ[j] <= 0.0 or d > 1.25 * (radii[i] + radii[j]):
            continue
        image = b.get('image') or [0, 0, 0]
        if len(image) != 3:
            continue
        bonded[i] = True
        bonded[j] = True
        left = labels[i]
        right = labels[j]
        delta = [shifts[i][k] + image[k] - shifts[j][k] for k in range(3)]
        if left == right:
            if any(x != 0 for x in delta):
                periodic[left] = True
        else:
            periodic[left] = periodic[left] or periodic[right]
            for k in range(n):
                if labels[k] == right:
                    labels[k] = left
                    shifts[k] = [shifts[k][a] + delta[a] for a in range(3)]
    total = sum(occ[i] for i in range(n) if bonded[i] and not periodic[labels[i]])
    return total / max(sum(occ), 1e-12)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    matrix = (s.get('lattice') or {}).get('matrix') or []
    if len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    moments = [[0.0, 0.0, 0.0, 0.0] for x in sites]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d < 6.0):
            continue
        if occ[i] <= 0.0 or occ[j] <= 0.0:
            continue
        u = d / (1.5 * (radii[i] + radii[j]))
        w = occ[j] * max(0.0, 1.0 - u * u) ** 2
        if w <= 0.0:
            continue
        position = sites[i].get('frac_coords') or []
        other = sites[j].get('frac_coords') or []
        image = b.get('image') or [0, 0, 0]
        if len(position) != 3 or len(other) != 3 or len(image) != 3:
            continue
        delta = [other[k] + image[k] - position[k] for k in range(3)]
        vector = [sum(delta[k] * matrix[k][a] for k in range(3)) for a in range(3)]
        norm2 = sum(x * x for x in vector)
        if norm2 <= 1e-12:
            continue
        scale = w / norm2 ** 0.5
        for a in range(3):
            moments[i][a] += scale * vector[a]
        moments[i][3] += w
    total = 0.0
    weight = 0.0
    for i in range(n):
        if moments[i][3] > 1e-12 and occ[i] > 0.0:
            value = sum(moments[i][a] ** 2 for a in range(3)) / moments[i][3] ** 2
            total += occ[i] * min(1.0, max(0.0, value))
            weight += occ[i]
    return total / max(weight, 1e-12)

def feature(s):
    if not s:
        return 0.0
    volume = s.get('volume_per_atom_A3') or 0.0
    if volume <= 0.0:
        sites = s.get('sites') or []
        count = sum(max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites)
        cell = (s.get('lattice') or {}).get('volume_A3') or 0.0
        if cell <= 0.0 or count <= 0.0:
            return 0.0
        volume = cell / count
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        valence = (props.get(element) or {}).get('valence_electrons')
        if fraction is not None and fraction > 0.0 and valence is not None and valence >= 0.0:
            total += fraction * valence
            weight += fraction
    return total / (max(weight, 1e-12) * volume)
